{
  "items": [
    {
      "name": "AkraBazziRecurrence.eventually_atTop_sumTransform_ge",
      "module_name": "Mathlib.Computability.AkraBazzi.SumTransform",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : Fintype α] {T : ℕ → ℝ} {g : ℝ → ℝ} {a b : α → ℝ} {r : α → ℕ → ℕ} [inst_1 : Nonempty α]\n  (R : AkraBazziRecurrence T g a b r),\n  ∃ c > 0,\n    ∀ᶠ (n : ℕ) in Filter.atTop,\n      ∀ (i : α), c * g ↑n ≤ AkraBazziRecurrence.sumTransform (AkraBazziRecurrence.p a b) g (r i n) n"
    },
    {
      "name": "Finset.le_sum_schlomilch",
      "module_name": "Mathlib.Analysis.PSeries",
      "kind": "theorem",
      "type": "∀ {M : Type u_1} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M] {f : ℕ → M} {u : ℕ → ℕ},\n  (∀ ⦃m n : ℕ⦄, 0 < m → m ≤ n → f n ≤ f m) →\n    (∀ (n : ℕ), 0 < u n) →\n      Monotone u →\n        ∀ (n : ℕ),\n          ∑ k ∈ Finset.range (u n), f k ≤\n            ∑ k ∈ Finset.range (u 0), f k + ∑ k ∈ Finset.range n, (u (k + 1) - u k) • f (u k)"
    },
    {
      "name": "le_hasSum_of_le_sum",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.Order",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_3} {L : SummationFilter ι} [inst : Preorder α] [inst_1 : AddCommMonoid α]\n  [inst_2 : TopologicalSpace α] {a c : α} {f : ι → α} [ClosedIciTopology α] [L.NeBot],\n  HasSum f a L → (∀ (s : Finset ι), c ≤ ∑ i ∈ s, f i) → c ≤ a"
    },
    {
      "name": "Chebyshev.psi_eq_theta_add_sum_theta",
      "module_name": "Mathlib.NumberTheory.Chebyshev",
      "kind": "theorem",
      "type": "∀ {x : ℝ},\n  2 ≤ x →\n    Chebyshev.psi x = Chebyshev.theta x + ∑ n ∈ Finset.Icc 2 ⌊Real.log x / Real.log 2⌋₊, Chebyshev.theta (x ^ (1 / ↑n))"
    },
    {
      "name": "ENNReal.le_iInf_add_iInf",
      "module_name": "Mathlib.Data.ENNReal.Operations",
      "kind": "theorem",
      "type": "∀ {ι : Sort u_1} {f : ι → ENNReal} {a : ENNReal} {κ : Sort u_2} {g : κ → ENNReal},\n  (∀ (i : ι) (j : κ), a ≤ f i + g j) → a ≤ iInf f + iInf g"
    },
    {
      "name": "Chebyshev.theta_le_log4_mul_x",
      "module_name": "Mathlib.NumberTheory.Chebyshev",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, 0 ≤ x → Chebyshev.theta x ≤ Real.log 4 * x"
    }
  ]
}
